  embellish = {
    [12384]={cn="奥纹内衬",en="Arcanoweave Lining",icon="inv_elemental_primal_mana",sp=1283697,dcn="你的法术和技能有几率吸引一只法力浮龙，以 奥纹洞察 强化你和一名盟友，使你的主要属性提高24点，盟友的主要属性提高6点",den="Your spells and abilities have a chance to draw in a mana wyrm that will empower you and an ally with Arcanoweave Insight , increasing your Primary Stat by 24 and your ally's Primary Stat by 6"},
    [12385]={cn="阳炎丝绸内衬",en="Sunfire Silk Lining",icon="inv_elemental_primal_mana",sp=1241711,dcn="周期性效果的治疗和伤害可使主要属性提高5点，持续15秒，最多叠加5次",den="Healing and damage from periodic effects can increase Primary Stat by 5 for 15 sec, stacking up to 5 times"},
    [12685]={cn="吞噬绑带",en="Devouring Banding",icon="inv_cosmicvoid_buff",sp=1244238,dcn="你的伤害法术和技能可以使你听从低语并向目标发射一道吞噬箭矢，造成1387点宇宙伤害。此箭矢会吞噬目标的力量，为你夺取60最高的次要属性，持续10秒",den="Your damaging spells and abilities can cause you to heed the whispers and fire a Devouring Bolt at your target, dealing 1387 Cosmic damage. This bolt devours their strength, seizing 60 of your highest secondary stat for you for 10 sec"},
    [12693]={cn="狩猎",en="Hunt",icon="inv_ability_hunter_deathchakram",sp=1245054,dcn="根据目标生物类型，你的法术和技能有几率会使你的次要属性提高56，持续15秒",den="Your spells and abilities have the chance to grant 56 secondary stats for 15 sec based on the target creature's type"},
    [13453]={cn="棱光聚焦之虹",en="Prismatic Focusing Iris",icon="inv_10_dungeonjewelry_dragon_trinket_1arcanemagical_green",sp=1251906,dcn="你的法术和技能有几率激活聚焦之虹，向你的目标发射聚焦光束，每秒造成1084点奥术伤害，持续4秒。\n\n镶嵌宝石每有一种不同的颜色，得到强化的虹膜造成额外1%伤害",den="Your spells and abilities have a chance to activate the Iris, firing a focused beam of light at your target and dealing 1084 Arcane damage every second for 4 sec.\n\nEach unique gem color you have socketed empowers the Iris, causing it to deal 1% additional damage per"},
    [13454]={cn="稳定式宝石弹药带",en="Stabilizing Gemstone Bandolier",icon="jewelcrafting_cut-epic-gem_color2",sp=1251905,dcn="宝石加倍，力量加倍！\n\n所有珠宝加工修饰都以双倍强度生效",den="Double the gems, double the power!\n\nAll Jewelcrafting embellishments operate at double strength"},
    [13640]={cn="虚空",en="Void",icon="inv_10_inscription3_darkmoondeckbox_black",sp=1245052,dcn="你的伤害法术和技能有几率使你在虚空琉璃中获得勇气，在15秒内获得40全能。多次施加可以重叠生效",den="Your damaging spells and abilities have the chance to embolden you in Void Glass granting 40 Versatility over 15 sec. Multiple applications can overlap"},
    [13767]={cn="华饰尖牙",en="Adorned Fang",icon="jewelcrafting_cut-epic-gem_color2",sp=1296870,dcn="你的法术和技能有一定几率使你获得 尖牙奔涌。 尖牙奔涌 使你的急速提高18，该效果最多可叠加3层。 \n攻击或治疗生命值较低的目标会提高此几率",den="Your spells and abilities have a chance to imbue you with Rush of Fangs . Rush of Fangs increases your Haste by 18. This effect can stack up to 3 times. \nAttacking or healing targets at lower health will increase this chance"},
    [13771]={cn="猎人仪式石",en="Hunter's Ritual Stone",icon="inv_elemental_primal_mana",sp=1297382,dcn="你的伤害性法术和技能有一定几率使一项随机次要属性提高101，持续15秒。\n\n在猎物追猎期间，此效果提高50%。该加成仅在户外追猎猎物时生效",den="Your damaging spells and abilities have a chance to grant 101 of a random secondary stat for 15 sec.\n\nWhile on a Prey Hunt this effect is increased by 50%. This bonus is only available outdoors while hunting prey"},
  },
